# Minimal WebGL2 check in this sandbox: Playwright 1.64.0 driving the pre-installed Chromium 141 build (chromium-1194).
# Run with:  /path/to/venv/bin/python -I recipe_min.py
from playwright.sync_api import sync_playwright

CHROME = "/opt/pw-browsers/chromium-1194/chrome-linux/chrome"

PROBE = """() => {
  const gl = document.createElement('canvas').getContext('webgl2');
  if (!gl) return {webgl2: false};
  const dbg = gl.getExtension('WEBGL_debug_renderer_info');
  return {
    webgl2: true,
    version: gl.getParameter(gl.VERSION),
    unmasked_renderer: dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : null,
    MAX_TEXTURE_SIZE: gl.getParameter(gl.MAX_TEXTURE_SIZE),
    MAX_3D_TEXTURE_SIZE: gl.getParameter(gl.MAX_3D_TEXTURE_SIZE),
    MAX_RENDERBUFFER_SIZE: gl.getParameter(gl.MAX_RENDERBUFFER_SIZE),
  };
}"""

with sync_playwright() as p:
    browser = p.chromium.launch(executable_path=CHROME, headless=True)
    page = browser.new_page()
    page.set_content("<!doctype html><title>webgl2</title>")
    print(page.evaluate(PROBE))
    browser.close()
